<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/client';const occupancy=ref<any>({}),sla=ref<any>({}),aging=ref<any[]>([]),deposits=ref<any[]>([]),rentRoll=ref<any[]>([]);async function load(){const[o,s,a,d,r]=await Promise.all([api.get('/reports/occupancy'),api.get('/reports/maintenance-sla'),api.get('/reports/receivable-aging'),api.get('/reports/deposit-reconciliation'),api.get('/reports/rent-roll')]);occupancy.value=o.data;sla.value=s.data;aging.value=a.data.items||[];deposits.value=d.data.items||[];rentRoll.value=r.data.items||[]}async function exportReport(type:string){const response=await api.get(`/reports/${type}/export`,{responseType:'blob'});const url=URL.createObjectURL(response.data);const anchor=document.createElement('a');anchor.href=url;anchor.download=`${type}.csv`;anchor.click();URL.revokeObjectURL(url)}onMounted(load)</script>
<template><div class="page"><div class="page-title"><div><h1>经营报表</h1><p>实时汇总入住率、租金台账、应收账龄、押金差异和维修 SLA</p></div><div class="action-group"><button class="secondary-button" @click="exportReport('rent-roll')">导出租金台账</button><button class="secondary-button" @click="exportReport('receivable-aging')">导出应收账龄</button><button class="primary-button" @click="exportReport('deposit-reconciliation')">导出押金对账</button></div></div><div class="stat-grid"><div class="stat-card"><span>房源总数</span><strong>{{occupancy.TotalUnits||0}}</strong></div><div class="stat-card"><span>已出租</span><strong>{{occupancy.OccupiedUnits||0}}</strong></div><div class="stat-card"><span>入住率</span><strong>{{((occupancy.OccupancyBasisPoints||0)/100).toFixed(2)}}%</strong></div><div class="stat-card"><span>超时工单</span><strong>{{sla.Overdue||0}}</strong></div></div><section class="card"><div class="card-title"><h3>租金台账</h3><span>{{rentRoll.length}} 条租约</span></div><table class="data-table"><thead><tr><th>房源</th><th>租客</th><th>租期</th><th>状态</th><th>月租金(分)</th><th>押金(分)</th></tr></thead><tbody><tr v-for="x in rentRoll" :key="x.LeaseID"><td>{{x.Building}} {{x.Room}}</td><td>{{x.TenantName}}</td><td>{{x.StartDate}} 至 {{x.EndDate}}</td><td>{{x.LeaseStatus}}</td><td>{{x.MonthlyRent}}</td><td>{{x.Deposit}}</td></tr></tbody></table></section><section class="card"><div class="card-title"><h3>应收账龄</h3><span>按逾期区间汇总</span></div><table class="data-table"><thead><tr><th>租客</th><th>房源</th><th>未到期</th><th>1-30天</th><th>31-60天</th><th>61-90天</th><th>90天以上</th><th>合计</th></tr></thead><tbody><tr v-for="x in aging" :key="x.LeaseID"><td>{{x.TenantName}}</td><td>{{x.PropertyLabel}}</td><td>{{x.Current}}</td><td>{{x.Days1To30}}</td><td>{{x.Days31To60}}</td><td>{{x.Days61To90}}</td><td>{{x.DaysOver90}}</td><td><strong>{{x.Total}}</strong></td></tr></tbody></table></section><section class="card"><div class="card-title"><h3>押金对账</h3><span>合同约定与资金流水核对</span></div><table class="data-table"><thead><tr><th>租客</th><th>房源</th><th>合同押金</th><th>流水余额</th><th>差异</th></tr></thead><tbody><tr v-for="x in deposits" :key="x.LeaseID"><td>{{x.TenantName}}</td><td>{{x.PropertyLabel}}</td><td>{{x.ContractDeposit}}</td><td>{{x.LedgerBalance}}</td><td>{{x.Difference}}</td></tr></tbody></table></section></div></template>
